from __future__ import annotations

import secrets
from typing import List, Tuple


def _validate_dimensions(dimensions: List[int]) -> None:
    if not isinstance(dimensions, list) or not dimensions:
        raise ValueError("dimensions must be a non-empty list of integers")
    for size in dimensions:
        if not isinstance(size, int) or isinstance(size, bool):
            raise TypeError("each dimension must be an integer")
        if size <= 0:
            raise ValueError("each dimension must be a positive integer")


def _build_nested(dimensions: List[int]) -> list:
    if not dimensions:
        return 0
    head, *tail = dimensions
    return [_build_nested(tail) for _ in range(head)]


def _generate_intervals(dimensions: List[int]) -> List[Tuple[int, int]]:
    rng = secrets.SystemRandom()
    intervals: List[Tuple[int, int]] = []
    for size in dimensions:
        begin = rng.randrange(size)
        end = rng.randrange(begin, size)
        intervals.append((begin, end))
    return intervals


def _validate_intervals(
    dimensions: List[int], intervals: List[Tuple[int, int]]
) -> None:
    if len(intervals) != len(dimensions):
        raise ValueError("intervals must match the number of dimensions")
    for (begin, end), size in zip(intervals, dimensions):
        if not all(isinstance(v, int) and not isinstance(v, bool) for v in (begin, end)):
            raise TypeError("interval bounds must be integers")
        if not (0 <= begin <= end < size):
            raise ValueError("interval out of bounds: require 0 <= begin <= end < size")


def _slice_nested(array: list, intervals: List[Tuple[int, int]]) -> list:
    begin, end = intervals[0]
    selected = array[begin : end + 1]
    if len(intervals) == 1:
        return list(selected)
    return [_slice_nested(element, intervals[1:]) for element in selected]


def subset_array(
    dimensions: List[int],
    intervals: List[Tuple[int, int]] | None = None,
) -> list:
    _validate_dimensions(dimensions)
    array = _build_nested(dimensions)
    if intervals is None:
        intervals = _generate_intervals(dimensions)
    else:
        intervals = [tuple(interval) for interval in intervals]
    _validate_intervals(dimensions, intervals)
    return _slice_nested(array, intervals)
