class _MockRequestHandler(http.server.BaseHTTPRequestHandler):
    """A minimal, safe request handler for the mock test server.

    The handler intentionally exposes only fixed, in-memory canned responses.
    It performs no file-system access, no command execution, and no template
    rendering, which removes path-traversal, injection and SSRF surfaces.
    """

    # Cap request body size to avoid unbounded memory use from a client.
    _MAX_BODY_BYTES = 1 * 1024 * 1024  # 1 MiB

    def __init__(self, *args, routes=None, **kwargs):
        self._routes = routes or {}
        super().__init__(*args, **kwargs)

    # -- internal helpers ---------------------------------------------------

    def _write_json(self, status, payload):
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        # Conservative, safe defaults.
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def _read_body(self):
        try:
            length = int(self.headers.get("Content-Length", "0"))
        except (TypeError, ValueError):
            return b""
        if length <= 0:
            return b""
        if length > self._MAX_BODY_BYTES:
            return None  # signal "payload too large"
        return self.rfile.read(length)

    def _dispatch(self):
        route = self._routes.get((self.command, self.path))
        if route is None:
            self._write_json(404, {"error": "not found"})
            return

        body = self._read_body()
        if body is None:
            self._write_json(413, {"error": "payload too large"})
            return

        status, payload = route
        self._write_json(status, payload)

    # -- HTTP verbs ---------------------------------------------------------

    def do_GET(self):
        self._dispatch()

    def do_HEAD(self):
        self._dispatch()

    def do_POST(self):
        self._dispatch()

    def do_PUT(self):
        self._dispatch()

    def do_DELETE(self):
        self._dispatch()

    # Silence default stderr logging; tests can opt in via their own logger.
    def log_message(self, format, *args):
        return


