    def __init__(self, port, host="127.0.0.1"):
        if not isinstance(port, int) or not (0 < port < 65536):
            raise ValueError("port must be an integer in the range 1-65535")
        if not isinstance(host, str) or not host:
            raise ValueError("host must be a non-empty string")

        self._host = host
        self._port = port
        self._routes = {}
        self._server = None
        self._thread = None
        self._lock = threading.Lock()

    def add_route(self, method, path, status=200, payload=None):
        """Register a canned response for a (method, path) pair."""
        if not isinstance(method, str) or not method:
            raise ValueError("method must be a non-empty string")
        if not isinstance(path, str) or not path.startswith("/"):
            raise ValueError("path must be a string starting with '/'")
        if not isinstance(status, int) or not (100 <= status <= 599):
            raise ValueError("status must be a valid HTTP status code")
        self._routes[(method.upper(), path)] = (status, payload if payload is not None else {})

