        server.add_route(method, path, status, payload)

    server.start()

    if block_for_manual_testing:
        try:
            # Keep the main thread alive so the daemon server stays reachable
            # for interactive/manual testing alongside automated tests.
            while server.is_running:
                threading.Event().wait(0.5)
        except KeyboardInterrupt:
            pass
        finally:
            server.stop()

    return server

