import numpy as np


def space_to_depth(x, block):
    if not isinstance(x, np.ndarray):
        raise TypeError("x must be a numpy.ndarray")
    if x.ndim != 4:
        raise ValueError("x must be a 4D array with shape (n, c, h, w)")
    if not isinstance(block, (int, np.integer)) or isinstance(block, bool):
        raise TypeError("block must be an integer")
    block = int(block)
    if block <= 0:
        raise ValueError("block must be a positive integer")

    n, c, h, w = x.shape
    if h % block != 0 or w % block != 0:
        raise ValueError("h and w must both be divisible by block")

    y = x.reshape(n, c, h // block, block, w // block, block)
    y = y.transpose(0, 3, 5, 1, 2, 4)
    y = y.reshape(n, c * (block ** 2), h // block, w // block)
