import sys
from datetime import date, timedelta
from pathlib import Path


def get_date_components(target: date) -> dict[str, int]:
    """Return the year, month and day of the given date."""
    return {"year": target.year, "month": target.month, "day": target.day}


def get_previous_date(reference: date, days_passed: int) -> date:
    """Return the date `days_passed` days before `reference`.

    `days_passed` must be a non-negative integer.
    """
    if not isinstance(days_passed, int) or isinstance(days_passed, bool):
        raise TypeError("days_passed must be an integer")
    if days_passed < 0:
        raise ValueError("days_passed must be non-negative")
    return reference - timedelta(days=days_passed)


def read_last_entry(
    file_name: str = "last_entry",
    data_dir: str = "data",
    base_dir: Path | None = None,
) -> str | None:
    """Safely read the last non-empty line from `data/last_entry`.

    The resolved path is confined to `data_dir` to prevent path traversal,
    and the file size is capped to avoid unbounded memory usage.
    """
    max_bytes = 10 * 1024 * 1024  # 10 MiB safety cap

    root = (base_dir or Path.cwd()).resolve()
    data_root = (root / data_dir).resolve()

    # Reject any file name that attempts to escape the data directory.
    candidate = (data_root / file_name).resolve()
    if candidate != data_root and data_root not in candidate.parents:
        raise ValueError("Resolved path escapes the data directory")

    try:
        if not candidate.is_file():
            return None
        if candidate.stat().st_size > max_bytes:
            raise ValueError("last_entry file exceeds the allowed size")

        last_line: str | None = None
        with candidate.open("r", encoding="utf-8", errors="replace") as handle:
            for raw_line in handle:
                stripped = raw_line.strip()
                if stripped:
